// Code map: a compact, generated index of the repo — every source file with its
// exported symbols (and line numbers) and how many other files import it.
// Agents read this one file instead of running many searches. Regenerated by the
// SessionStart hook when any source file is newer than the map. Zero model tokens to
// build; ~1 line per file to read.
import fs from 'node:fs';
import path from 'node:path';
import { git, tmpDir, SOURCE_EXT, isTestFile } from './common.mjs';

const EXCLUDE_RE = /(^|\/)(node_modules|dist|build|out|coverage|vendor|target|\.next|\.nuxt|\.venv|venv|__pycache__|\.n-stack|generated|gen)\/|\.min\.[jc]ss?$|\.d\.ts$/;
const MAX_FILE_BYTES = 300_000;
const MAX_SYMBOLS = 10;
const SPLIT_THRESHOLD = 300; // above this many source files, write an index + per-area files
const CORE_FILES = 60;

export const codemapPath = (root) => path.join(tmpDir(root), 'codemap.md');

function listFiles(root) {
  const r = git(['ls-files', '--cached', '--others', '--exclude-standard'], root, 30_000);
  if (r.code !== 0) throw new Error('not a git repository');
  return r.stdout.split('\n').map((f) => f.trim()).filter((f) => f && SOURCE_EXT.has(path.extname(f).toLowerCase()) && !EXCLUDE_RE.test(f));
}

export function isStale(root) {
  const map = codemapPath(root);
  if (!fs.existsSync(map)) return true;
  const mapTime = fs.statSync(map).mtimeMs;
  const files = listFiles(root);
  const header = fs.readFileSync(map, 'utf8').match(/files: (\d+)/);
  if (!header || Number(header[1]) !== files.length) return true;
  return files.some((f) => { try { return fs.statSync(path.join(root, f)).mtimeMs > mapTime; } catch { return true; } });
}

const lineAt = (text, index) => text.slice(0, index).split('\n').length;

function symbols(file, text) {
  const ext = path.extname(file).toLowerCase();
  const out = [];
  const add = (name, idx) => { if (name && !out.some((s) => s.name === name)) out.push({ name, line: lineAt(text, idx) }); };
  let m;
  const scan = (re, group = 1) => { re.lastIndex = 0; while ((m = re.exec(text))) add(m[group], m.index); };

  if (['.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs', '.vue', '.svelte'].includes(ext)) {
    scan(/^export\s+(?:default\s+)?(?:declare\s+)?(?:async\s+)?(?:abstract\s+)?(?:function\*?|class|const|let|var|interface|type|enum)\s+([A-Za-z_$][\w$]*)/gm);
    const named = /^export\s*\{([^}]*)\}/gm;
    while ((m = named.exec(text))) {
      for (const part of m[1].split(',')) add(part.trim().split(/\s+as\s+/).pop(), m.index);
    }
    if (/^export\s+default\s+(?!function|class|async)/m.test(text)) add('default', text.search(/^export\s+default/m));
    scan(/^\s*(?:module\.)?exports\.([A-Za-z_$][\w$]*)\s*=/gm);
  } else if (ext === '.py') {
    scan(/^(?:async\s+)?def\s+([A-Za-z]\w*)/gm);
    scan(/^class\s+([A-Za-z]\w*)/gm);
  } else if (ext === '.go') {
    scan(/^func\s+(?:\([^)]*\)\s*)?([A-Z]\w*)/gm);
    scan(/^type\s+([A-Z]\w*)/gm);
  } else if (ext === '.rs') {
    scan(/^\s*pub\s+(?:async\s+)?(?:fn|struct|enum|trait|type|mod|const)\s+(\w+)/gm);
  } else if (['.java', '.kt', '.cs', '.swift'].includes(ext)) {
    scan(/^\s*(?:public|open|internal)\s+(?:static\s+|final\s+|abstract\s+|sealed\s+|data\s+)*(?:class|interface|enum|record|struct|object|func|fun)\s+(\w+)/gm);
  } else if (ext === '.rb') {
    scan(/^\s*(?:class|module)\s+([A-Z]\w*)/gm);
    scan(/^\s*def\s+(?:self\.)?([a-z_]\w*[?!]?)/gm);
  } else if (ext === '.php') {
    scan(/^\s*(?:final\s+|abstract\s+)?(?:class|interface|trait|enum)\s+(\w+)/gm);
    scan(/^\s*public\s+(?:static\s+)?function\s+(\w+)/gm);
  }
  return out;
}

const JS_EXT = ['.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs'];

function resolveImport(fromFile, spec, fileSet) {
  const ext = path.extname(fromFile).toLowerCase();
  if (ext === '.py') {
    // relative (from .x import y) or absolute module path (from app.models import User)
    let mod = spec;
    let baseDir = '';
    const dots = (spec.match(/^\.+/) || [''])[0].length;
    if (dots) {
      baseDir = path.posix.dirname(fromFile);
      for (let i = 1; i < dots; i++) baseDir = path.posix.dirname(baseDir);
      mod = spec.slice(dots);
    }
    const rel = path.posix.join(baseDir, mod.replace(/\./g, '/'));
    return [`${rel}.py`, `${rel}/__init__.py`].find((c) => fileSet.has(c.replace(/^\.\//, ''))) || null;
  }
  if (!spec.startsWith('.')) return null;
  const joined = path.posix.normalize(path.posix.join(path.posix.dirname(fromFile), spec));
  const noJs = joined.replace(/\.(m|c)?js$/, '');
  const candidates = [joined, ...JS_EXT.map((e) => noJs + e), ...JS_EXT.map((e) => `${joined}/index${e}`)];
  return candidates.find((c) => fileSet.has(c)) || null;
}

function imports(file, text) {
  const ext = path.extname(file).toLowerCase();
  const specs = [];
  let m;
  if (JS_EXT.includes(ext) || ext === '.vue' || ext === '.svelte') {
    const re = /(?:import|export)[^'"`;]*?from\s*['"]([^'"]+)['"]|import\(\s*['"]([^'"]+)['"]\s*\)|require\(\s*['"]([^'"]+)['"]\s*\)|^\s*import\s+['"]([^'"]+)['"]/gm;
    while ((m = re.exec(text))) specs.push(m[1] || m[2] || m[3] || m[4]);
  } else if (ext === '.py') {
    const re = /^\s*from\s+([.\w]+)\s+import|^\s*import\s+([\w.]+)/gm;
    while ((m = re.exec(text))) specs.push(m[1] || m[2]);
  }
  return specs;
}

export function generate(root) {
  const files = listFiles(root);
  const fileSet = new Set(files);
  const info = new Map();
  const importedBy = new Map();

  for (const f of files) {
    let text = '';
    try {
      const st = fs.statSync(path.join(root, f));
      if (st.size <= MAX_FILE_BYTES) text = fs.readFileSync(path.join(root, f), 'utf8');
    } catch { continue; }
    info.set(f, { lines: text ? text.split('\n').length : 0, symbols: isTestFile(f) ? [] : symbols(f, text) });
    for (const spec of imports(f, text)) {
      const target = resolveImport(f, spec, fileSet);
      if (target && target !== f) importedBy.set(target, (importedBy.get(target) || 0) + 1);
    }
  }

  const groups = new Map();
  for (const f of files) {
    const parts = f.split('/');
    const key = parts.length > 2 ? parts.slice(0, 2).join('/') : (parts.length === 2 ? parts[0] : '.');
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(f);
  }

  const sha = git(['rev-parse', '--short', 'HEAD'], root).stdout.trim() || 'uncommitted';
  const fileLine = (f) => {
    const i = info.get(f) || { lines: 0, symbols: [] };
    const used = importedBy.get(f) ? `, imported by ${importedBy.get(f)}` : '';
    const syms = i.symbols.slice(0, MAX_SYMBOLS).map((s) => `${s.name}:${s.line}`).join(', ');
    const more = i.symbols.length > MAX_SYMBOLS ? ` +${i.symbols.length - MAX_SYMBOLS} more` : '';
    return `- \`${f}\` (${i.lines}${used})${syms ? `: ${syms}${more}` : ''}`;
  };
  const groupSection = (key) => {
    const list = groups.get(key);
    const lines = [`## ${key}/`, ...list.filter((f) => !isTestFile(f)).map(fileLine)];
    const tests = list.filter((f) => isTestFile(f));
    if (tests.length) lines.push(`- tests: ${tests.map((t) => t.split('/').pop()).join(', ')}`);
    return [...lines, ''];
  };
  const header = [
    `# Code map (generated at ${sha}, files: ${files.length}) — do not edit`,
    '',
    'Each line: file (lines, imported by N files): exported symbol:line. Most-imported files are the core.',
    'Use it to pick files to read; confirm details by reading the file. Tests are listed by name only.',
    '',
  ];
  const keys = [...groups.keys()].sort();
  const detailDir = path.join(tmpDir(root), 'codemap');
  fs.rmSync(detailDir, { recursive: true, force: true });

  if (files.length <= SPLIT_THRESHOLD) {
    fs.writeFileSync(codemapPath(root), [...header, ...keys.flatMap(groupSection)].join('\n'));
    return { files: files.length, path: codemapPath(root) };
  }

  // Large repo: a small index (areas + the core files) so reading the map stays cheap,
  // plus one detail file per area that agents open only for the area they work in.
  fs.mkdirSync(detailDir, { recursive: true });
  const detailName = (key) => `${key.replace(/[\\/]/g, '__')}.md`;
  const index = [...header, '## Areas', '', '| Area | Source files | Detail |', '|---|---|---|'];
  for (const key of keys) {
    fs.writeFileSync(path.join(detailDir, detailName(key)), [`# Code map: ${key}/ (at ${sha})`, '', ...groupSection(key)].join('\n'));
    const n = groups.get(key).filter((f) => !isTestFile(f)).length;
    index.push(`| \`${key}/\` | ${n} | .n-stack/tmp/codemap/${detailName(key)} |`);
  }
  const core = [...importedBy.entries()].sort((a, b) => b[1] - a[1]).slice(0, CORE_FILES).map(([f]) => f);
  index.push('', `## Core files (${core.length} most imported)`, '', ...core.map(fileLine), '');
  fs.writeFileSync(codemapPath(root), index.join('\n'));
  return { files: files.length, path: codemapPath(root) };
}
